package kernels

// amd64 GEMM micro-kernel: a 6x8 register-blocked tile (gemm in sum_amd64.s,
// generated by go-asmgen), the BLIS Haswell dgemm shape. Two kernels share the
// one 6x8 packing:
//
//   - gemmMicro6x8FMA, AVX2-era FMA3: 12 YMM accumulators, VBROADCASTSD of each
//     A value and VFMADD231PD against the two-YMM B row. Taken when hasFMA
//     (CPUID FMA, AVX and OSXSAVE, and XCR0 saving YMM state) says so — every
//     Intel and AMD part since 2013.
//   - gemmMicro6x4SSE2, the GOAMD64=v1 baseline, called twice per tile (columns
//     0-3, then 4-7): explicit MULPD+ADDPD, since SSE2 has no FMA.
//
// The FMA kernel rounds each a*b+c once, as tuned BLAS and arm64's kernel do; the
// SSE2 one rounds twice, as the scalar oracle does at GOAMD64=v1. On data whose
// products and partial sums are exact (the integer-valued tests) the two agree
// bit-for-bit with the oracle; elsewhere they can differ in the last place.

// MR, NR are the micro-kernel's register-block dimensions: it computes an
// MR-row x NR-col tile of C per call. The packing in gemm.go matches.
const (
	MR = 6
	NR = 8
)

// useFMA selects the FMA kernels (GEMM, dot). It is a var so tests can force
// the SSE2 / pure-Go paths on hardware that has FMA (never the reverse: that
// would fault).
var useFMA = hasFMA()

// gemmMicro adds the MR x NR tile sum_p pa[p*MR..]*pb[p*NR..] into the C block at
// dst[0:], whose rows are ldc apart. pa, pb hold at least kc*MR and kc*NR packed
// (zero-padded) doubles; dst has at least (MR-1)*ldc + NR elements.
func gemmMicro(kc int, pa, pb, dst []float64, ldc int) {
	_, _, _ = pa[kc*MR-1], pb[kc*NR-1], dst[(MR-1)*ldc+NR-1] // the kernel's whole reach
	if useFMA {
		gemmMicro6x8FMA(kc, &pa[0], &pb[0], &dst[0], ldc)
		return
	}
	gemmMicro6x4SSE2(kc, &pa[0], &pb[0], &dst[0], ldc)
	gemmMicro6x4SSE2(kc, &pa[0], &pb[4], &dst[4], ldc)
}

// gemmMicroUA is the unpacked-A float64 kernel (see gemmKernel.microUA), on
// FMA CPUs only; without FMA, A is packed for the SSE2 kernel.
var gemmMicroUA = microUAIf(useFMA)

func microUAIf(fma bool) func(kc int, a []float64, lda int, pb, dst []float64, ldc, mr int) {
	if !fma {
		return nil
	}
	return gemmMicroUA64
}

// gemmUA64 holds the unpacked-A kernels by tile height.
var gemmUA64 = [...]func(kc int, a *float64, lda int, pb, c *float64, ldc int){
	1: gemmUA1x8FMA, 2: gemmUA2x8FMA, 3: gemmUA3x8FMA,
	4: gemmUA4x8FMA, 5: gemmUA5x8FMA, 6: gemmUA6x8FMA,
}

// gemmMicroUA64 adds the mr x 8 tile sum_p a[r*lda+p]*pb[p*8..] into dst,
// whose rows are ldc apart, reading A in place (mr in 1..6, lda > 0).
func gemmMicroUA64(kc int, a []float64, lda int, pb, dst []float64, ldc, mr int) {
	_, _, _ = a[(mr-1)*lda+kc-1], pb[kc*NR-1], dst[(mr-1)*ldc+NR-1] // the kernel's whole reach
	gemmUA64[mr](kc, &a[0], lda, &pb[0], &dst[0], ldc)
}

//go:noescape
func gemmUA1x8FMA(kc int, a *float64, lda int, pb, c *float64, ldc int)

//go:noescape
func gemmUA2x8FMA(kc int, a *float64, lda int, pb, c *float64, ldc int)

//go:noescape
func gemmUA3x8FMA(kc int, a *float64, lda int, pb, c *float64, ldc int)

//go:noescape
func gemmUA4x8FMA(kc int, a *float64, lda int, pb, c *float64, ldc int)

//go:noescape
func gemmUA5x8FMA(kc int, a *float64, lda int, pb, c *float64, ldc int)

//go:noescape
func gemmUA6x8FMA(kc int, a *float64, lda int, pb, c *float64, ldc int)

//go:noescape
func gemmMicro6x8FMA(kc int, pa, pb, c *float64, ldc int)

//go:noescape
func gemmMicro6x4SSE2(kc int, pa, pb, c *float64, ldc int)

// dotSIMD is the inner product of two equal-length slices: the AVX2/FMA
// kernel when the CPU has FMA, else dotRange.
func dotSIMD(a, b []float64) float64 {
	if !useFMA || len(a) == 0 {
		return dotRange(a, b)
	}
	_ = b[len(a)-1] // the kernel reads len(a) of b
	return dotFMA(&a[0], &b[0], len(a))
}

//go:noescape
func dotFMA(a, b *float64, n int) float64

// hasFMA reports CPU and OS support for the FMA kernel (go-asmgen FeatureProbe).
func hasFMA() bool
